 $('connectMetaApi').onclick=async()=>{const token=$('metaApiToken').value.trim(),account=$('metaApiAccount').value.trim(),page=$('metaApiPage').value.trim();if(!token||!account)return msg('Enter a Meta access token and ad account ID.',true);$('connectMetaApi').disabled=true;$('connectMetaApi').textContent='Connecting…';const r=await sb.functions.invoke('meta-campaign-api',{body:{action:'connect',rollout_id:id,access_token:token,ad_account_id:account,page_id:page}});$('connectMetaApi').disabled=false;$('connectMetaApi').textContent='Connect Meta';if(r.error||r.data?.error)return msg(r.data?.error||r.error.message,true);$('metaApiToken').value='';if(page){$('fbPageId').value=page;await saveMeta(false)}metaAudienceCheck=null;await load();msg(r.data?.connection?.page_warning?'Meta ad account connected. Page validation returned a warning; M2 can still create campaign/ad sets.':'Meta connected successfully.');switchHub('meta')};
