 $('metaAudiencePreflight').onclick=async()=>{if(!metaApi.connected)return msg('Connect Meta first.',true);if(!await saveMeta(false))return;$('metaAudiencePreflight').disabled=true;$('metaAudiencePreflight').textContent='Checking…';const r=await sb.functions.invoke('meta-campaign-api',{body:{action:'preflight',rollout_id:id}});$('metaAudiencePreflight').disabled=false;$('metaAudiencePreflight').textContent='Check audiences';if(r.error||r.data?.error){metaAudienceCheck=null;renderMetaApi();return msg(r.data?.error||r.error.message,true)}metaAudienceCheck=r.data;renderMetaApi();msg(r.data.ok?'All local Meta audiences matched.':`${r.data.missing?.length||0} audience names are missing in Meta.`,!r.data.ok)};
 async function createMetaDraftBatch(allowMissing=false){if(!metaAudienceCheck)return msg('Run the audience check first.',true);if(!allowMissing&&!metaAudienceCheck.ok)return msg('Some Meta audiences are missing. Use the TEST override if you deliberately want broad GB targeting.',true);const warning=allowMissing?`TEST OVERRIDE: create one PAUSED Meta campaign and ${data.sites.length} PAUSED local ad sets? Areas without a matching Custom Audience will use BROAD GB targeting. Nothing will be published or spend money.`:`Create one PAUSED Meta campaign and ${data.sites.length} PAUSED local ad sets? Nothing will be published or spend money.`;if(!confirm(warning))return;if(!await saveMeta(false))return;const btn=allowMissing?$('createMetaDraftsOverride'):$('createMetaDrafts');btn.disabled=true;const oldText=btn.textContent;btn.textContent='Creating drafts…';const r=await sb.functions.invoke('meta-campaign-api',{body:{action:'create_drafts',rollout_id:id,app_root:appRoot(),allow_missing_audiences:allowMissing}});btn.textContent=oldText;if(r.error||r.data?.error){await load();return msg(r.data?.error||r.error.message,true)}await load();msg(`${r.data.created}/${r.data.expected} PAUSED local ad sets created in Meta.${allowMissing?' Missing audiences used broad GB targeting.':''}`);switchHub('meta')};$('createMetaDrafts').onclick=()=>createMetaDraftBatch(false);$('createMetaDraftsOverride').onclick=()=>createMetaDraftBatch(true);['fbCampaignPattern','fbAdSetPattern','fbAdPattern','fbBody','fbHeadline','fbDescription','fbCta','fbDailyBudget','fbPageId','fbBaseUrl','fbAudiencePattern'].forEach(i=>$(i).addEventListener('input',renderMetaPreflight));$('saveMeta').onclick=()=>saveMeta(true);$('metaForm').onsubmit=async e=>{e.preventDefault();if($('downloadMeta').disabled)return;if(!await saveMeta(false))return;const rows=metaRows().map(r=>META_HEADERS.map(h=>r[h]));if(!window.RC_XLSX)return msg('Workbook generator did not load. Refresh and try again.',true);window.RC_XLSX.download(`${slugify(data.rollout.title)}-meta-ready.xlsx`,META_HEADERS,rows,'Ads');msg(`${rows.length} Meta ad row${rows.length===1?'':'s'} exported in the proven workbook format.`)};
 async function blobToDataUrl(blob){return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error||new Error('Could not read generated graphic'));r.readAsDataURL(blob)})}

 function defaultWebsiteDesign(){const p=data?.rollout?.package||{},b=brand();return {version:1,width:'normal',primary:b.primary,secondary:b.secondary,sections:[{type:'hero',label:'Hero',visible:true,eyebrow:'{{area}}',title:p.headline||data.rollout.title,copy:p.supporting_copy||'',button:p.cta||'Back this campaign',padding:70},{type:'intro',label:'Campaign message',visible:true,title:'Why this matters in {{area}}',copy:p.supporting_copy||'',padding:55},{type:'points',label:'Key points',visible:true,title:'Our campaign for {{area}}',copy:'',padding:55},{type:'support',label:'Sign-up',visible:true,title:p.cta||'Back this campaign',copy:'Add your details to support this campaign in {{area}}.',button:p.cta||'Back this campaign',padding:55},{type:'footer',label:'Footer',visible:true,title:data.rollout.title,copy:'{{area}}',padding:28}]}}
 function ensureWebsite(){if(!websiteDesign){const saved=brand().websiteStudio;websiteDesign=saved&&Array.isArray(saved.sections)?JSON.parse(JSON.stringify(saved)):defaultWebsiteDesign();websiteSelected=Math.min(websiteSelected,websiteDesign.sections.length-1)}}
 function websiteSite(){const s=(data.sites||[]).find(x=>x.id===$('websiteArea')?.value)||(data.sites||[])[0]||{area:'Your area',slug:'your-area'};return effectiveSite(s)}
 function websiteVar(v,site=websiteSite()){return replaceArea(String(v||''),site)}
 function renderWebsitePanel(){ensureWebsite();const area=$('websiteArea');if(!area)return;const old=area.value;area.innerHTML=(data.sites||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.area)}</option>`).join('');area.value=(data.sites||[]).some(x=>x.id===old)?old:((data.sites||[])[0]?.id||'');$('websitePrimary').value=websiteDesign.primary||brand().primary;$('websiteSecondary').value=websiteDesign.secondary||brand().secondary;$('websiteWidth').value=websiteDesign.width||'normal';renderWebsiteSections();renderWebsiteControls();renderWebsitePreview();$('websiteStatus').textContent=websiteDirty?'Unsaved changes':'Saved master site'}
 function renderWebsiteSections(){const el=$('websiteSections');if(!el)return;el.innerHTML=websiteDesign.sections.map((x,i)=>`<div class="website-section-row ${i===websiteSelected?'active':''}" data-ws-index="${i}"><strong>${esc(x.label||x.type)}</strong><div class="website-section-actions"><button type="button" data-ws-up="${i}" title="Move up">↑</button><button type="button" data-ws-down="${i}" title="Move down">↓</button><button type="button" data-ws-toggle="${i}" title="Show/hide">${x.visible===false?'○':'●'}</button>${x.type==='text'?`<button type="button" data-ws-delete="${i}">×</button>`:''}</div></div>`).join('')}
 function renderWebsiteControls(){const el=$('websiteControls'),sec=websiteDesign.sections[websiteSelected];if(!el||!sec)return;el.innerHTML=`<label>Section name<input data-ws-field="label" value="${esc(sec.label||'')}"></label>${sec.type!=='footer'?`<label>Heading<input data-ws-field="title" value="${esc(sec.title||'')}"></label>`:''}${['hero','intro','text','support','footer'].includes(sec.type)?`<label>Copy<textarea data-ws-field="copy">${esc(sec.copy||'')}</textarea></label>`:''}${['hero','support'].includes(sec.type)?`<label>Button text<input data-ws-field="button" value="${esc(sec.button||'')}"></label>`:''}${sec.type==='hero'?`<label>Eyebrow<input data-ws-field="eyebrow" value="${esc(sec.eyebrow||'')}"></label>`:''}<label>Vertical spacing<input data-ws-field="padding" type="range" min="20" max="100" value="${Number(sec.padding||50)}"></label><label><span><input data-ws-field="visible" type="checkbox" ${sec.visible===false?'':'checked'}> Show section</span></label>`;el.querySelectorAll('[data-ws-field]').forEach(input=>{input.oninput=()=>{const f=input.dataset.wsField;sec[f]=input.type==='checkbox'?input.checked:input.type==='range'?Number(input.value):input.value;websiteDirty=true;renderWebsitePreview();renderWebsiteSections();$('websiteStatus').textContent='Unsaved changes'}})}
 function renderWebsitePreview(){const el=$('websitePreviewFrame');if(!el)return;const site=websiteSite(),b=brand(),o=localOverride(site),primary=o.primary||websiteDesign.primary||b.primary,secondary=o.secondary||websiteDesign.secondary||b.secondary,hero=o.hero_image||site.branding?.hero_image||b.hero,sections=websiteDesign.sections.filter(x=>x.visible!==false);el.classList.toggle('mobile',websiteDevice==='mobile');const points=Array.isArray(site.key_points)?site.key_points:[];let body='';for(const sec of sections){const pad=`style="padding-top:${Number(sec.padding||50)}px;padding-bottom:${Number(sec.padding||50)}px"`;if(sec.type==='hero')body+=`<section class="ws-hero" ${hero?`style="background-image:linear-gradient(90deg,rgba(5,30,58,.86),rgba(5,30,58,.45)),url('${esc(hero)}');padding-top:${Number(sec.padding||70)}px;padding-bottom:${Number(sec.padding||70)}px"`:pad}><div class="ws-hero-inner"><div class="ws-kicker">${esc(websiteVar(sec.eyebrow,site))}</div><h1>${esc(websiteVar(sec.title,site))}</h1><p>${esc(websiteVar(sec.copy,site))}</p><span class="ws-btn">${esc(websiteVar(sec.button,site))}</span></div></section>`;else if(sec.type==='intro'||sec.type==='text')body+=`<section class="ws-section ${sec.type==='text'?'alt':''}" ${pad}><h2>${esc(websiteVar(sec.title,site))}</h2><p>${esc(websiteVar(sec.copy,site))}</p></section>`;else if(sec.type==='points')body+=`<section class="ws-section" ${pad}><h2>${esc(websiteVar(sec.title,site))}</h2><div class="ws-points">${(points.length?points:['Local campaign point','A second local point','A third local point']).slice(0,3).map(p=>`<div class="ws-point"><strong>${esc(websiteVar(typeof p==='string'?p:(p.title||''),site))}</strong></div>`).join('')}</div></section>`;else if(sec.type==='support')body+=`<section class="ws-section alt" ${pad}><div class="ws-support"><div><h2>${esc(websiteVar(sec.title,site))}</h2><p>${esc(websiteVar(sec.copy,site))}</p></div><div class="ws-form"><div></div><div></div><div></div><span class="ws-btn">${esc(websiteVar(sec.button,site))}</span></div></div></section>`;else if(sec.type==='footer')body+=`<footer class="ws-footer" ${pad}><strong>${esc(websiteVar(sec.title,site))}</strong><small> ${esc(websiteVar(sec.copy,site))}</small></footer>`}el.innerHTML=`<div class="ws-page" style="--ws-primary:${esc(primary)};--ws-secondary:${esc(secondary)}"><header class="ws-header"><span>${esc(data.rollout.title)}</span><small>${esc(site.area)}</small></header>${body}</div>`;el.querySelectorAll('.ws-btn').forEach(x=>x.style.background=secondary);el.querySelectorAll('.ws-hero').forEach(x=>x.style.backgroundColor=primary)}
 async function saveWebsiteStudio(){ensureWebsite();const b=data.rollout.package?.branding||{},payload={...b,website_studio:websiteDesign};const r=await sb.rpc('org_admin_update_rapid_campaign_design',{p_rollout:id,p_branding:payload});if(r.error)return msg(r.error.message,true);data.rollout.package.branding=payload;websiteDirty=false;$('websiteStatus').textContent='Saved master site';msg('Website Studio master saved. All local microsites now use it.')}


 function renderMetaRefresh(){const btn=$('refreshMetaAds'),status=$('metaM5Status');if(!btn||!status)return;const drafts=metaApi?.drafts||[],ads=drafts.filter(d=>d.ad_id);btn.disabled=!metaApi?.connected||!ads.length;status.innerHTML=!ads.length?'Create the Meta Ads first.':`<span><strong>${ads.length}</strong> existing Meta Ad${ads.length===1?'':'s'} ready to refresh from the current saved design and copy.</span>`}
 async function refreshMetaAds(){const drafts=(metaApi?.drafts||[]).filter(d=>d.ad_id);if(!drafts.length)return msg('There are no existing Meta Ads to refresh.',true);if(studioDirty&&!confirm('Creative Studio has unsaved changes. Refresh Meta using the unsaved design currently on screen? Cancel if you want to save it first.'))return;if(!confirm(`Refresh ${drafts.length} existing Meta Ad creative${drafts.length===1?'':'s'}? This will replace the image and ad copy on the existing Ads, keep the same Ad IDs and Ad Sets, and force them to remain PAUSED.`))return;const btn=$('refreshMetaAds');btn.disabled=true;const old=btn.textContent;const img=await getHeroImage(),logo=await getLogoImage();let done=0;for(let i=0;i<drafts.length;i++){const d=drafts[i],site=(data.sites||[]).find(s=>s.id===d.site_id)||(data.sites||[]).find(s=>s.area===d.area);btn.textContent=`Refreshing ${i+1}/${drafts.length}…`;if(!site){msg(`${d.area}: local site not found.`,true);continue}try{const blob=await graphicBlob(site,img,logo),imageBase64=await blobToDataUrl(blob);const r=await sb.functions.invoke('meta-refresh-ad',{body:{rollout_id:id,site_id:site.id,image_base64:imageBase64}});if(r.error||r.data?.error){msg(`${d.area}: ${r.data?.error||r.error.message}`,true);continue}done++}catch(e){msg(`${d.area}: ${e.message}`,true)}}btn.textContent=old;await load();switchHub('meta');msg(`${done}/${drafts.length} Meta creative${drafts.length===1?'':'s'} refreshed. Existing Ads and Ad Sets were retained and remain PAUSED.`,done!==drafts.length)}
 async function createMetaAds(){const drafts=metaApi?.drafts||[],pending=drafts.filter(d=>d.adset_id&&!d.ad_id);if(!pending.length)return msg('There are no missing Meta Ads to create.');if(!confirm(`Create ${pending.length} PAUSED Meta Ad${pending.length===1?'':'s'} now? Rapid Campaign will generate and upload the graphics, create the Ad Creatives and place the Ads into the existing M2 Ad Sets. Nothing will be published or spend money.`))return;const btn=$('createMetaAds');btn.disabled=true;const img=await getHeroImage(),logo=await getLogoImage();let created=0;for(let i=0;i<pending.length;i++){const d=pending[i],site=(data.sites||[]).find(s=>s.id===d.site_id)|| (data.sites||[]).find(s=>s.area===d.area);if(!site){msg(`Could not find local site for ${d.area}.`,true);continue}btn.textContent=`Creating ${i+1}/${pending.length}…`;try{const blob=await graphicBlob(site,img,logo),imageBase64=await blobToDataUrl(blob);const r=await sb.functions.invoke('meta-create-ad',{body:{rollout_id:id,site_id:site.id,image_base64:imageBase64}});if(r.error||r.data?.error){msg(`${d.area}: ${r.data?.error||r.error.message}`,true);continue}created++}catch(e){msg(`${d.area}: ${e.message}`,true)}}btn.textContent='Create PAUSED Ads';await load();switchHub('meta');msg(`${created}/${pending.length} PAUSED Meta Ad${pending.length===1?'':'s'} created.${created===pending.length?' M3 complete.':' Check the failed area messages above.'}`,created!==pending.length)}
 $('createMetaAds').onclick=createMetaAds;
 $('refreshMetaAds').onclick=refreshMetaAds;
 function defaultFormQuestions(){return [
  {type:'first_name',key:'first_name',label:'First name',required:false,tag_answer:false},
  {type:'last_name',key:'last_name',label:'Last name',required:false,tag_answer:false},
  {type:'email',key:'email',label:'Email address',required:true,tag_answer:false},
  {type:'postcode',key:'postcode',label:'Postcode',required:true,tag_answer:false},
  {type:'consent',key:'consent',label:'I would like to receive campaign updates by email.',required:false,tag_answer:false}
 ]}
 function formTypeLabel(t){return ({first_name:'First name',last_name:'Last name',email:'Email',postcode:'Postcode',phone:'Phone',single_choice:'Single choice',multi_choice:'Multi choice',short_text:'Short text',long_text:'Long text',consent:'Consent'})[t]||'Field'}
 function formCurrent(){const f=campaignForm.form||{};return {name:f.name||'Main form',form_type:f.form_type||'signup',title:f.title||'Back this campaign',intro:f.intro||'Add your details and tell us what matters to you.',submit_label:f.submit_label||'Submit',success_message:f.success_message||'Thank you — your response has been recorded.'}}
 function formKeyBase(t){return ({single_choice:'question',multi_choice:'choices',short_text:'response',long_text:'feedback'})[t]||t}
 function uniqueFormKey(base){const used=new Set(formQuestions.map(q=>q.key));let k=slugify(base).replace(/-/g,'_')||'question',n=2,root=k;while(used.has(k))k=`${root}_${n++}`;return k}
 function renderFormQuestionList(){const el=$('formQuestionList');if(!el)return;el.innerHTML=formQuestions.length?formQuestions.map((q,i)=>`<div class="form-question-row ${i===formSelected?'active':''}"><button type="button" data-form-select="${i}"><strong>${esc(q.label||formTypeLabel(q.type))}</strong><br><small>${esc(formTypeLabel(q.type))}${q.required?' · Required':''}</small></button><div class="form-question-actions"><button type="button" title="Move up" data-form-up="${i}">↑</button><button type="button" title="Move down" data-form-down="${i}">↓</button><button type="button" title="Delete" data-form-delete="${i}">×</button></div></div>`).join(''):'<span class="studio-muted">Add fields to start building the form.</span>'}
 function renderFormQuestionControls(){const el=$('formQuestionControls');if(!el)return;const q=formQuestions[formSelected];if(!q){el.innerHTML='<span class="studio-muted">Choose a field to edit it.</span>';return}const choices=['single_choice','multi_choice'].includes(q.type);el.innerHTML=`<label>Label<input id="fqLabel" value="${esc(q.label||'')}"></label><label>Field key<input id="fqKey" value="${esc(q.key||'')}"></label>${choices?`<label>Choices<textarea id="fqChoices" rows="6" placeholder="One choice per line">${esc((q.options||[]).join('\n'))}</textarea></label>`:''}<label class="question-inline"><input id="fqRequired" type="checkbox" ${q.required?'checked':''}> Required</label>${!['first_name','last_name','email','postcode','phone','consent'].includes(q.type)?`<label class="question-inline"><input id="fqTag" type="checkbox" ${q.tag_answer?'checked':''}> Turn answer into CRM tag</label>`:''}`;const update=()=>{q.label=$('fqLabel').value;q.key=uniqueKeyWithoutSelf($('fqKey').value,formSelected);q.required=$('fqRequired').checked;if($('fqChoices'))q.options=$('fqChoices').value.split('\n').map(x=>x.trim()).filter(Boolean);if($('fqTag'))q.tag_answer=$('fqTag').checked;renderFormQuestionList();renderFormPreview()};['fqLabel','fqKey','fqChoices','fqRequired','fqTag'].forEach(k=>{const x=$(k);if(x)x.addEventListener(x.type==='checkbox'?'change':'input',update)})}
 function uniqueKeyWithoutSelf(v,index){let base=slugify(v).replace(/-/g,'_')||`field_${index+1}`,k=base,n=2;const used=new Set(formQuestions.filter((_,i)=>i!==index).map(q=>q.key));while(used.has(k))k=`${base}_${n++}`;return k}
 function renderFormPreview(){const el=$('formPreview');if(!el)return;const f=formCurrent(),title=$('formTitle')?.value||f.title,intro=$('formIntro')?.value||f.intro,submit=$('formSubmitLabel')?.value||f.submit_label;const fields=formQuestions.map(q=>{const req=q.required?' <small>Required</small>':'';if(q.type==='consent')return `<label class="form-preview-choice"><input type="checkbox" disabled> <span>${esc(q.label||'Consent')}${req}</span></label>`;if(q.type==='single_choice'||q.type==='multi_choice')return `<div class="form-preview-field"><span>${esc(q.label||'Question')}${req}</span>${(q.options||['Option one','Option two']).map(o=>`<label class="form-preview-choice"><input type="${q.type==='single_choice'?'radio':'checkbox'}" disabled> ${esc(o)}</label>`).join('')}</div>`;if(q.type==='long_text')return `<label class="form-preview-field"><span>${esc(q.label||'Response')}${req}</span><textarea rows="4" disabled></textarea></label>`;return `<label class="form-preview-field"><span>${esc(q.label||formTypeLabel(q.type))}${req}</span><input type="${q.type==='email'?'email':'text'}" disabled></label>`}).join('');el.innerHTML=`<h3>${esc(title)}</h3>${intro?`<p>${esc(intro)}</p>`:''}${fields}<button class="btn" type="button" disabled>${esc(submit)}</button>`}
 function renderFormResponses(){const el=$('formResponses');if(!el)return;$('formResponseCount').textContent=`${campaignForm.responses||0} response${Number(campaignForm.responses||0)===1?'':'s'}`;el.innerHTML=formResponses.length?`<div class="performance-table-wrap"><table class="performance-table"><thead><tr><th>Area</th><th>Answers</th><th>Date</th></tr></thead><tbody>${formResponses.map(r=>`<tr><td><strong>${esc(r.area||'—')}</strong></td><td><div class="form-response-answer">${Object.entries(r.answers||{}).map(([k,v])=>`<span><strong>${esc(k)}:</strong> ${esc(Array.isArray(v)?v.join(', '):v)}</span>`).join('')||'—'}</div></td><td>${esc(new Date(r.created_at).toLocaleString())}</td></tr>`).join('')}</tbody></table></div>`:'<div class="simple-note"><span>No form responses yet.</span></div>'}
