 async function saveCampaignForm(){if(!formQuestions.some(q=>q.type==='email'||q.type==='postcode'))return msg('Add an email or postcode field so the supporter can be identified.',true);const btn=$('saveCampaignForm'),old=btn.textContent;btn.disabled=true;btn.textContent='Saving…';try{const r=await sb.rpc('org_admin_save_rapid_campaign_form',{p_rollout:id,p_name:$('formName').value.trim(),p_form_type:$('formType').value,p_title:$('formTitle').value.trim(),p_intro:$('formIntro').value.trim(),p_submit_label:$('formSubmitLabel').value.trim(),p_success_message:$('formSuccessMessage').value.trim(),p_questions:formQuestions});if(r.error)throw r.error;campaignForm.form={...(campaignForm.form||{}),id:r.data,name:$('formName').value.trim(),form_type:$('formType').value,title:$('formTitle').value.trim(),intro:$('formIntro').value.trim(),submit_label:$('formSubmitLabel').value.trim(),success_message:$('formSuccessMessage').value.trim(),questions:clone(formQuestions)};msg('Form saved. Every live microsite now uses this form.');renderFormBuilder()}catch(e){msg(e.message||String(e),true)}finally{btn.disabled=false;btn.textContent=old}}
