 function renderDnsSetup(){const el=$('domainDnsSetup');if(!el)return;if(!domainConnection||domainMode()!=='existing'){el.innerHTML='';return}const d=domainConnection,verified=['verified','connected'].includes(d.status);el.innerHTML=`<div class="simple-note" style="margin-top:16px"><strong>${verified?'Ownership verified':'Add this DNS record'}</strong><span>${verified?'Rapid Campaign found the verification token in public DNS.':'At the DNS provider for '+esc(d.hostname)+', create the TXT record below. DNS changes can take a few minutes to appear.'}</span></div><div class="performance-table-wrap" style="margin-top:12px"><table class="performance-table"><thead><tr><th>Type</th><th>Name</th><th>Value</th><th></th></tr></thead><tbody><tr><td><strong>TXT</strong></td><td><code>${esc(d.txt_name)}</code></td><td><code>${esc(d.txt_value)}</code></td><td><button class="btn secondary small" type="button" data-copy-domain="${esc(d.txt_value)}">Copy</button></td></tr></tbody></table></div><div class="domain-connect-actions" style="margin-top:12px"><button class="btn ${verified?'secondary':''}" type="button" data-verify-domain>${verified?'Check again':'Verify DNS'}</button><span class="domain-inline-status">${d.last_checked_at?'Last checked '+esc(new Date(d.last_checked_at).toLocaleString()):''}</span></div>${verified?`<div class="state-banner success" style="margin-top:12px">Domain ownership verified. The final production-routing step will be activated through Cloudflare for SaaS; until then, keep using the temporary Rapid Campaign URL for live traffic.</div>`:''}`}
 async function saveDomain(mode,domain=''){if(mode==='temporary'){const res=await sb.rpc('org_admin_clear_campaign_domain',{p_rollout:id});if(res.error)return msg(res.error.message,true);msg('Campaign switched to the temporary Rapid Campaign URL.');await load();renderDomainHub();fillMetaForm();return}const value=normaliseDomainInput(domain);if(!value)return msg('Enter a domain first.',true);const host=value.replace(/^https?:\/\//,'');const res=await sb.rpc('org_admin_prepare_existing_domain',{p_rollout:id,p_hostname:host});if(res.error)return msg(res.error.message,true);domainConnection=res.data;msg(`Domain attached: ${host}. Add the TXT record and verify DNS.`);await load();renderDomainHub();fillMetaForm()}
